import React, { useState, useEffect, useMemo } from "react";
import {
    Container,
    Row,
    Col,
    Card,
    Nav,
    Table,
    Button,
    Form,
    InputGroup,
    Alert,
    Spinner,
    Modal,
    Toast,
    Pagination,
    Badge
} from "react-bootstrap";
import axios from "axios";

const PAGE_SIZE = 8;

const ADMIN = () => {
    const [activeTab, setActiveTab] = useState("lecturers");
    const [lecturers, setLecturers] = useState([]);
    const [students, setStudents] = useState([]);
    const [courses, setCourses] = useState([]);
    const [modules, setModules] = useState([]);
    const [searchInput, setSearchInput] = useState("");
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState({ students: false, lecturers: false });
    const [error, setError] = useState("");

    // Modal / form state
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState("add"); // 'add' | 'edit'
    const [modalEntity, setModalEntity] = useState("lecturer"); // 'lecturer' | 'student'
    const [form, setForm] = useState({ staffNumber: "", studentNumber: "", name: "", surname: "", dateOfBirth: "", homeAddress: "", phoneNumber: "" });

    // Toast
    const [toast, setToast] = useState({ show: false, message: "", variant: "success" });

    // Pagination & sort
    const [page, setPage] = useState(1);
    const [sortAsc, setSortAsc] = useState(true);

    useEffect(() => {
        getStudentData();
        getLecturerData();
    }, []);

    // Debounce search input
    useEffect(() => {
        const t = setTimeout(() => setSearch(searchInput.trim()), 300);
        return () => clearTimeout(t);
    }, [searchInput]);

    const getStudentData = async () => {
        try {
            setLoading(prev => ({ ...prev, students: true }));
            setError("");
            const result = await axios.get("https://localhost:7281/api/Student/GetStudents");
            setStudents(result.data || []);
        } catch (err) {
            console.error("Error fetching students:", err);
            setError("Failed to load students. Please check if the server is running.");
        } finally {
            setLoading(prev => ({ ...prev, students: false }));
        }
    };

    const getLecturerData = async () => {
        try {
            setLoading(prev => ({ ...prev, lecturers: true }));
            setError("");
            const result = await axios.get("https://localhost:7281/api/Lecturer/GetAllLecturers");
            setLecturers(result.data || []);
        } catch (err) {
            console.error("Error fetching lecturers:", err);
            setError("Failed to load lecturers. Please check if the server is running.");
        } finally {
            setLoading(prev => ({ ...prev, lecturers: false }));
        }
    };

    // Logout
    const handleLogout = () => {
        localStorage.clear();
        sessionStorage.clear();
        window.location.reload();
    };

    // Modal handlers
    const openAddModal = (entity) => {
        setModalType("add");
        setModalEntity(entity);
        setForm({ staffNumber: "", studentNumber: "", name: "", surname: "", dateOfBirth: "", homeAddress: "", phoneNumber: "" });
        setShowModal(true);
    };

    const openEditModal = (item, entity) => {
        setModalType("edit");
        setModalEntity(entity);
        setForm({
            staffNumber: item.staffNumber || "",
            studentNumber: item.studentNumber || "",
            name: item.name || "",
            surname: item.surname || "",
            dateOfBirth: item.dateOfBirth ? new Date(item.dateOfBirth).toISOString().slice(0, 10) : "",
            homeAddress: item.homeAddress || "",
            phoneNumber: item.phoneNumber || "",
            id: item.lecturerId || item.studentId || item.id
        });
        setShowModal(true);
    };

    const handleModalChange = (e) => setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));

    const showToast = (message, variant = "success") => {
        setToast({ show: true, message, variant });
        setTimeout(() => setToast(t => ({ ...t, show: false })), 3000);
    };

    const handleSubmitModal = async () => {
        // Basic validation
        if (!form.name || !form.surname) {
            showToast("Name and surname are required", "danger");
            return;
        }

        try {
            if (modalEntity === "lecturer") {
                if (modalType === "add") {
                    // Example POST - adjust endpoint as needed
                    // const res = await axios.post("https://localhost:7281/api/Lecturer", { ...form });
                    const newLecturer = { lecturerId: Date.now(), ...form };
                    setLecturers(prev => [newLecturer, ...prev]);
                    showToast("Lecturer added");
                } else {
                    // const res = await axios.put(`https://localhost:7281/api/Lecturer/${form.id}`, { ...form });
                    setLecturers(prev => prev.map(l => (l.lecturerId === form.id || l.id === form.id) ? { ...l, ...form } : l));
                    showToast("Lecturer updated");
                }
            } else {
                if (modalType === "add") {
                    // const res = await axios.post("https://localhost:7281/api/Student", { ...form });
                    const newStudent = { studentId: Date.now(), ...form };
                    setStudents(prev => [newStudent, ...prev]);
                    showToast("Student added");
                } else {
                    // const res = await axios.put(`https://localhost:7281/api/Student/${form.id}`, { ...form });
                    setStudents(prev => prev.map(s => (s.studentId === form.id || s.id === form.id) ? { ...s, ...form } : s));
                    showToast("Student updated");
                }
            }
            setShowModal(false);
        } catch (err) {
            console.error(err);
            showToast("Operation failed", "danger");
        }
    };

    const handleDelete = async (id, type) => {
        const confirm = window.confirm("Delete this item? This action cannot be undone.");
        if (!confirm) return;
        try {
            // await axios.delete(`https://localhost:7281/api/${type === 'lecturer' ? 'Lecturer' : 'Student'}/${id}`);
            if (type === "lecturer") setLecturers(prev => prev.filter(l => l.lecturerId !== id && l.id !== id));
            else setStudents(prev => prev.filter(s => s.studentId !== id && s.id !== id));
            showToast("Deleted");
        } catch (err) {
            console.error(err);
            showToast("Delete failed", "danger");
        }
    };

    // Filter + sort + pagination helpers
    const getFiltered = (items) => {
        const q = search.toLowerCase();
        const filtered = items.filter(it =>
            !q ||
            (it.name && it.name.toLowerCase().includes(q)) ||
            (it.surname && it.surname.toLowerCase().includes(q)) ||
            (it.staffNumber && it.staffNumber.toLowerCase().includes(q)) ||
            (it.studentNumber && it.studentNumber.toLowerCase().includes(q))
        );
        const sorted = filtered.sort((a, b) => {
            const an = (a.name || "").toLowerCase();
            const bn = (b.name || "").toLowerCase();
            if (an < bn) return sortAsc ? -1 : 1;
            if (an > bn) return sortAsc ? 1 : -1;
            return 0;
        });
        return sorted;
    };

    const displayedLecturers = useMemo(() => {
        const list = getFiltered(lecturers);
        const start = (page - 1) * PAGE_SIZE;
        return { pageItems: list.slice(start, start + PAGE_SIZE), total: list.length };
    }, [lecturers, search, sortAsc, page]);

    const displayedStudents = useMemo(() => {
        const list = getFiltered(students);
        const start = (page - 1) * PAGE_SIZE;
        return { pageItems: list.slice(start, start + PAGE_SIZE), total: list.length };
    }, [students, search, sortAsc, page]);

    const resetPaging = () => setPage(1);

    // When changing tab or search reset page
    useEffect(() => resetPaging(), [activeTab, search, sortAsc]);

    return (
        <Container fluid className="p-4">
            <Row className="mb-3">
                <Col>
                    <h1 className="fw-bold display-5 text-primary">Educore Learning Management System</h1>
                    <div className="text-muted">Administrator Dashboard — manage users, courses and modules</div>
                </Col>
                <Col className="text-end align-self-center">
                    <Button variant="outline-danger" size="sm" onClick={handleLogout}>Logout</Button>
                </Col>
            </Row>

            {error && <Alert variant="danger" className="mb-3">{error}</Alert>}

            <Row>
                <Col lg={9}>
                    <Card className="shadow-sm">
                        <Card.Header className="d-flex justify-content-between align-items-center">
                            <Nav variant="tabs" activeKey={activeTab} onSelect={(k) => setActiveTab(k)}>
                                <Nav.Item><Nav.Link eventKey="lecturers">Lecturers</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="students">Students</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="courses">Courses</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="modules">Modules</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="assign">Assignments</Nav.Link></Nav.Item>
                            </Nav>

                            <div>
                                <Badge bg="secondary" className="me-2">Sort: {sortAsc ? "A→Z" : "Z→A"}</Badge>
                                <Button size="sm" variant="outline-secondary" onClick={() => setSortAsc(s => !s)}>Toggle Sort</Button>
                            </div>
                        </Card.Header>

                        <Card.Body>
                            <div className="mb-3 d-flex gap-2">
                                <InputGroup style={{ maxWidth: 420 }}>
                                    <Form.Control placeholder="Search by name, surname, or number" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} />
                                    <Button variant="primary" onClick={() => setSearch(searchInput.trim())}>Search</Button>
                                </InputGroup>

                                <div className="ms-auto">
                                    {activeTab === "lecturers" && <Button onClick={() => openAddModal("lecturer")}>Add Lecturer</Button>}
                                    {activeTab === "students" && <Button onClick={() => openAddModal("student")}>Add Student</Button>}
                                </div>
                            </div>

                            {/* Lecturers */}
                            {activeTab === "lecturers" && (
                                <>
                                    <Table striped bordered hover responsive>
                                        <thead>
                                            <tr>
                                                <th>#</th>
                                                <th>First Name</th>
                                                <th>Last Name</th>
                                                <th>DOB</th>
                                                <th>Address</th>
                                                <th>Phone</th>
                                                <th className="text-center">Actions</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {loading.lecturers ? (
                                                <tr><td colSpan="7" className="text-center"><Spinner animation="border" /> Loading...</td></tr>
                                            ) : displayedLecturers.pageItems.length > 0 ? (
                                                displayedLecturers.pageItems.map((item, i) => (
                                                    <tr key={item.lecturerId || item.id || i}>
                                                        <td>{(page - 1) * PAGE_SIZE + i + 1}</td>
                                                        <td>{item.name || "N/A"}</td>
                                                        <td>{item.surname || "N/A"}</td>
                                                        <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString() : "N/A"}</td>
                                                        <td>{item.homeAddress || "N/A"}</td>
                                                        <td>{item.phoneNumber || "N/A"}</td>
                                                        <td className="text-center">
                                                            <Button size="sm" variant="outline-primary" onClick={() => openEditModal(item, "lecturer")}>Edit</Button>{' '}
                                                            <Button size="sm" variant="outline-danger" onClick={() => handleDelete(item.lecturerId || item.id, "lecturer")}>Delete</Button>
                                                        </td>
                                                    </tr>
                                                ))
                                            ) : (
                                                <tr><td colSpan="7" className="text-center">No lecturers found</td></tr>
                                            )}
                                        </tbody>
                                    </Table>

                                    <div className="d-flex justify-content-between align-items-center">
                                        <div className="text-muted">Showing {displayedLecturers.pageItems.length} of {displayedLecturers.total}</div>
                                        <Pagination size="sm" className="mb-0">
                                            {Array.from({ length: Math.max(1, Math.ceil(displayedLecturers.total / PAGE_SIZE)) }, (_, idx) => (
                                                <Pagination.Item key={idx} active={idx + 1 === page} onClick={() => setPage(idx + 1)}>{idx + 1}</Pagination.Item>
                                            ))}
                                        </Pagination>
                                    </div>
                                </>
                            )}

                            {/* Students */}
                            {activeTab === "students" && (
                                <>
                                    <Table striped bordered hover responsive>
                                        <thead>
                                            <tr>
                                                <th>#</th>
                                                <th>First Name</th>
                                                <th>Last Name</th>
                                                <th>DOB</th>
                                                <th>Address</th>
                                                <th>Phone</th>
                                                <th className="text-center">Actions</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {loading.students ? (
                                                <tr><td colSpan="7" className="text-center"><Spinner animation="border" /> Loading...</td></tr>
                                            ) : displayedStudents.pageItems.length > 0 ? (
                                                displayedStudents.pageItems.map((item, i) => (
                                                    <tr key={item.studentId || item.id || i}>
                                                        <td>{(page - 1) * PAGE_SIZE + i + 1}</td>
                                                        <td>{item.name || "N/A"}</td>
                                                        <td>{item.surname || "N/A"}</td>
                                                        <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString() : "N/A"}</td>
                                                        <td>{item.homeAddress || "N/A"}</td>
                                                        <td>{item.phoneNumber || "N/A"}</td>
                                                        <td className="text-center">
                                                            <Button size="sm" variant="outline-primary" onClick={() => openEditModal(item, "student")}>Edit</Button>{' '}
                                                            <Button size="sm" variant="outline-danger" onClick={() => handleDelete(item.studentId || item.id, "student")}>Delete</Button>
                                                        </td>
                                                    </tr>
                                                ))
                                            ) : (
                                                <tr><td colSpan="7" className="text-center">No students found</td></tr>
                                            )}
                                        </tbody>
                                    </Table>

                                    <div className="d-flex justify-content-between align-items-center">
                                        <div className="text-muted">Showing {displayedStudents.pageItems.length} of {displayedStudents.total}</div>
                                        <Pagination size="sm" className="mb-0">
                                            {Array.from({ length: Math.max(1, Math.ceil(displayedStudents.total / PAGE_SIZE)) }, (_, idx) => (
                                                <Pagination.Item key={idx} active={idx + 1 === page} onClick={() => setPage(idx + 1)}>{idx + 1}</Pagination.Item>
                                            ))}
                                        </Pagination>
                                    </div>
                                </>
                            )}

                            {/* Placeholder tabs */}
                            {activeTab === "courses" && (
                                <div className="text-center p-4">
                                    <h5>Courses Management</h5>
                                    <p className="text-muted">Functionality coming soon. You can add courses and assign lecturers/modules here.</p>
                                </div>
                            )}
                            {activeTab === "modules" && (
                                <div className="text-center p-4">
                                    <h5>Modules Management</h5>
                                    <p className="text-muted">Modules UI will appear here with assignment and progress tracking.</p>
                                </div>
                            )}
                            {activeTab === "assign" && (
                                <div className="text-center p-4">
                                    <h5>Assignments & Grading</h5>
                                    <p className="text-muted">Create assignments, set deadlines and manage submissions.</p>
                                </div>
                            )}
                        </Card.Body>
                    </Card>
                </Col>

                <Col lg={3}>
                    <Card className="shadow-sm">
                        <Card.Header><strong>Quick Actions</strong></Card.Header>
                        <Card.Body>
                            <p><strong>Counts</strong></p>
                            <div className="d-flex justify-content-between">
                                <div>Lecturers</div><div><Badge bg="info">{lecturers.length}</Badge></div>
                            </div>
                            <div className="d-flex justify-content-between mt-2">
                                <div>Students</div><div><Badge bg="info">{students.length}</Badge></div>
                            </div>

                            <hr />

                            <Button variant="outline-primary" className="w-100 mb-2" onClick={() => { setActiveTab("lecturers"); }}>Go to Lecturers</Button>
                            <Button variant="outline-primary" className="w-100 mb-2" onClick={() => { setActiveTab("students"); }}>Go to Students</Button>
                            <Button variant="outline-secondary" className="w-100" onClick={() => showToast("This is a demo toast", "info")}>Show Demo Toast</Button>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>

            {/* Add/Edit Modal */}
            <Modal show={showModal} onHide={() => setShowModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>{modalType === "add" ? "Add" : "Edit"} {modalEntity === "lecturer" ? "Lecturer" : "Student"}</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form>
                        {modalEntity === "lecturer" && <Form.Group className="mb-2">
                            <Form.Label>Staff Number</Form.Label>
                            <Form.Control name="staffNumber" value={form.staffNumber} onChange={handleModalChange} />
                        </Form.Group>}
                        {modalEntity === "student" && <Form.Group className="mb-2">
                            <Form.Label>Student Number</Form.Label>
                            <Form.Control name="studentNumber" value={form.studentNumber} onChange={handleModalChange} />
                        </Form.Group>}
                        <Form.Group className="mb-2">
                            <Form.Label>First Name</Form.Label>
                            <Form.Control name="name" value={form.name} onChange={handleModalChange} />
                        </Form.Group>
                        <Form.Group className="mb-2">
                            <Form.Label>Last Name</Form.Label>
                            <Form.Control name="surname" value={form.surname} onChange={handleModalChange} />
                        </Form.Group>
                        <Form.Group className="mb-2">
                            <Form.Label>Date of Birth</Form.Label>
                            <Form.Control type="date" name="dateOfBirth" value={form.dateOfBirth} onChange={handleModalChange} />
                        </Form.Group>
                        <Form.Group className="mb-2">
                            <Form.Label>Home Address</Form.Label>
                            <Form.Control name="homeAddress" value={form.homeAddress} onChange={handleModalChange} />
                        </Form.Group>
                        <Form.Group className="mb-2">
                            <Form.Label>Phone Number</Form.Label>
                            <Form.Control name="phoneNumber" value={form.phoneNumber} onChange={handleModalChange} />
                        </Form.Group>
                    </Form>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowModal(false)}>Cancel</Button>
                    <Button variant="primary" onClick={handleSubmitModal}>{modalType === "add" ? "Add" : "Save"}</Button>
                </Modal.Footer>
            </Modal>

            {/* Toast (top-right) */}
            <div style={{ position: "fixed", top: 16, right: 16, zIndex: 1060 }}>
                <Toast show={toast.show} bg={toast.variant === "danger" ? "danger" : (toast.variant === "info" ? "info" : "success")} onClose={() => setToast(t => ({ ...t, show: false }))}>
                    <Toast.Header>
                        <strong className="me-auto">Educore</strong>
                        <small>now</small>
                    </Toast.Header>
                    <Toast.Body className="text-white">{toast.message}</Toast.Body>
                </Toast>
            </div>
        </Container>
    );
};

export default ADMIN;
